package scimapp

// ConfigurationHTML is the shared SCIM setup section used by app templates.
const ConfigurationHTML = `{{with .SCIM}}<section class="wide integration-setup" id="integrations.scim"><h2>SCIM provisioning</h2><p>Connect a System for Cross-domain Identity Management (SCIM) 2.0 provider. Kinosail provisions Viewer Profiles and never grants Owner access.</p><div class="scim-endpoint"><div class="copy-field"><label>Base URL<input id="scim-base-url" aria-label="SCIM base URL" value="{{.Endpoint}}" readonly spellcheck="false"></label><button class="quiet" type="button" data-copy-target="scim-base-url">Copy URL</button><span class="copy-status" aria-live="polite"></span></div><p>Enter this URL in your provider. Use bearer token authentication.</p></div><p>{{if .Expired}}The configured token expired. Provisioning is disabled until you rotate it.{{else if .Configured}}SCIM is configured.{{else}}SCIM is not configured.{{end}}</p>{{if .Control.Managed}}<p>SCIM is configured outside Kinosail. Update the token and expiration together, then restart Kinosail Server.</p>{{range .Control.DockerVars}}<p>Configured via Docker: <code>{{.}}</code>.</p>{{end}}{{range .Control.YAMLKeys}}<p>Configured via YAML: <code>{{.}}</code>.</p>{{end}}{{else}}<form action="/settings/configuration" method="post"><input type="hidden" name="key" value="integrations.scim"><div class="scim-fields"><div class="copy-field"><label>Bearer token<input id="scim-bearer-token" aria-label="SCIM bearer token" name="token" type="password" value="{{.SuggestedToken}}" minlength="32" maxlength="256" autocomplete="new-password" placeholder="{{if .Configured}}Leave blank to keep the configured token{{else}}Bearer token{{end}}" {{if not .Configured}}required{{end}}></label><button class="quiet" type="button" data-copy-target="scim-bearer-token">Copy token</button><span class="copy-status" aria-live="polite"></span></div><label>Expires on<input aria-label="SCIM token expiration date" name="tokenExpiresOn" type="date" value="{{.ExpiresOn}}" min="{{.MinimumDate}}" max="{{.MaximumDate}}" required></label></div>{{if not .Configured}}<p>Copy the generated token into your provider before you save. Kinosail hides it after this page.</p>{{end}}<button>Save SCIM</button><p>Applies after a restart.</p></form>{{if .Configured}}<form action="/settings/configuration/reset" method="post"><button class="quiet" name="key" value="integrations.scim">Disable SCIM</button></form>{{end}}{{end}}<details><summary>Technical details</summary><p>Provider attributes: <code>userName</code>, <code>name</code>, <code>displayName</code>, <code>emails</code>, <code>externalId</code>, and <code>active</code>.</p><p>Configuration keys: <code>integrations.scim.token</code>, <code>integrations.scim.token_expires_at</code>.</p></details></section>{{end}}`
